        ctx.ellipse(1, 2, lp.r*0.95, lp.r*0.88, 0, 0, Math.PI*2);
        ctx.fill();
        // sprite
        var pw = lp.r*2.2, ph = pw * (lilyPadImg.height/lilyPadImg.width);
        ctx.drawImage(lilyPadImg, -pw/2, -ph/2, pw, ph);
