    bankPath(bankInner, false);
    // gradient: dark wet at water edge -> fading to dry
    var mudg = ctx.createRadialGradient(bcx, bcy, 150, bcx, bcy, 280);
    mudg.addColorStop(0, 'rgba(60,45,28,0)'); // transparent in water
    mudg.addColorStop(0.55, 'rgba(75,58,35,0.7)'); // wet mud (earthy, not black)
    mudg.addColorStop(0.75, 'rgba(95,75,48,0.4)'); // fading
    mudg.addColorStop(1, 'rgba(95,75,48,0)'); // to dry dirt
    ctx.fillStyle = mudg;
    ctx.fill('evenodd');
    ctx.restore();
    // DIRT TEXTURE: darker patches, pebbles
    ctx.save();
    ctx.beginPath();
