      var mp = pondPts[mmi];
      var mdx = mp.x - mcx, mdy = mp.y - mcy;
      var mdl = Math.sqrt(mdx*mdx+mdy*mdy) || 1;
      var mux = mdx/mdl, muy = mdy/mdl;
      mudOuter.push({x: mp.x + mux*10, y: mp.y + muy*10});
